/* Generated by equipe-design emit — do not edit by hand; change the tokens and emit again. */
@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

@theme {
  /* colour roles: bg-background, text-text, border-border … */
  --color-background: #f6f5f1;
  --color-surface: #ecebe7;
  --color-raised: #f1f0ec;
  --color-text: #15161a;
  --color-muted-text: #656567;
  --color-primary: #1d4ed8;
  --color-on-primary: #ffffff;
  --color-secondary: #e4e3e0;
  --color-accent: #1d4ed8;
  --color-border: #d0cfcc;
  --color-border-strong: #707072;
  --color-ring: #1d4ed8;
  --color-destructive: #c62828;
  --color-success: #1b7a43;
  --color-warning: #8f5b00;

  /* palette: bg-teal-600 … (the step is lightness, 0 light to 1000 dark) */
  --color-neutral-0: #ffffff;
  --color-neutral-25: #f6f5f1;
  --color-neutral-50: #ecebe7;
  --color-neutral-75: #f1f0ec;
  --color-neutral-100: #e4e3e0;
  --color-neutral-125: #efede7;
  --color-neutral-150: #d0cfcc;
  --color-neutral-375: #898886;
  --color-neutral-425: #7d7c7a;
  --color-neutral-450: #707072;
  --color-neutral-500: #656567;
  --color-neutral-750: #232324;
  --color-neutral-775: #1c1c1d;
  --color-neutral-800: #15161a;
  --color-neutral-825: #141416;
  --color-neutral-850: #0a0a0c;
  --color-neutral-875: #161618;
  --color-neutral-975: #000000;
  --color-green-200: #5fd68f;
  --color-green-500: #1b7a43;
  --color-yellow-200: #f0b44c;
  --color-yellow-475: #8f5b00;
  --color-violet-225: #8fb0ff;
  --color-orange-250: #ff8a80;
  --color-orange-450: #c62828;
  --color-blue-500: #1d4ed8;

  /* fonts */
  --font-sans: 'Inter Variable', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono Variable', ui-monospace, monospace;

  /* radius */
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* type roles: text-body, text-h1 … */
  --text-display: 56px;
  --text-display--line-height: 1.05;
  --text-display--letter-spacing: -0.02em;
  --text-display--font-weight: 600;
  --text-h1: 40px;
  --text-h1--line-height: 1.15;
  --text-h1--letter-spacing: -0.015em;
  --text-h1--font-weight: 700;
  --text-h2: 32px;
  --text-h2--line-height: 1.2;
  --text-h2--letter-spacing: -0.01em;
  --text-h2--font-weight: 600;
  --text-h3: 24px;
  --text-h3--line-height: 1.3;
  --text-h3--letter-spacing: 0em;
  --text-h3--font-weight: 600;
  --text-body: 16px;
  --text-body--line-height: 1.5;
  --text-body--letter-spacing: 0em;
  --text-body--font-weight: 400;
  --text-small: 14px;
  --text-small--line-height: 1.5;
  --text-small--letter-spacing: 0em;
  --text-small--font-weight: 400;
  --text-mono: 14px;
  --text-mono--line-height: 1.5;
  --text-mono--letter-spacing: 0em;
  --text-mono--font-weight: 400;

  /* shadow */
  --shadow-1: 0px 8px 24px 0px #15161a14;

  /* motion */
  --duration-fast: 160ms;
  --duration-base: 160ms;
  --duration-slow: 160ms;
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
}

.dark {
  --color-background: #0a0a0c;
  --color-surface: #141416;
  --color-raised: #1c1c1d;
  --color-text: #efede7;
  --color-muted-text: #898886;
  --color-primary: #8fb0ff;
  --color-on-primary: #000000;
  --color-secondary: #161618;
  --color-accent: #8fb0ff;
  --color-border: #232324;
  --color-border-strong: #7d7c7a;
  --color-ring: #8fb0ff;
  --color-destructive: #ff8a80;
  --color-success: #5fd68f;
  --color-warning: #f0b44c;
}
